// Existing fixture utility: local data synchronization, never a model/test launcher.
import { readFileSync, writeFileSync, mkdirSync, realpathSync, existsSync, lstatSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
const root = realpathSync(path.resolve(path.dirname(fileURLToPath(import.meta.url)), ".."));
const error = reason => { throw new Error(reason); };
const read = relative => {
  if (typeof relative !== "string" || path.isAbsolute(relative)) error("INVALID_INPUT_PATH");
  const full = realpathSync(path.resolve(root, relative));
  if (!full.startsWith(root + path.sep)) error("INPUT_OUTSIDE_FIXTURE");
  return JSON.parse(readFileSync(full, "utf8"));
};
try {
  const [action, target, ...extra] = process.argv.slice(2);
  if (!["sync", "finalize"].includes(action) || target !== "TEST-NOTICE" || extra.length) error("UNAPPROVED_TARGET_OR_ACTION");
  const routes = read("operations/route-map.json");
  if (typeof routes.noticeSource !== "string") error("MISSING_NOTICE_SOURCE_BINDING");
  const source = read(routes.noticeSource);
  if (source.fixture !== true || source.noticeId !== "demo-morning" || typeof source.title !== "string"
      || typeof source.window !== "string" || !Number.isSafeInteger(source.capacity) || source.capacity < 1) error("INVALID_NOTICE_SOURCE");
  const signoff = read("operator/signoff.json");
  if (signoff.fixture !== true || signoff.selectedNotice !== source.noticeId
      || !["PENDING", "APPROVED"].includes(signoff.printReview)) error("INVALID_OPERATOR_RECORD");
  if (action === "finalize" && signoff.printReview !== "APPROVED") {
    console.log(JSON.stringify({state:"USER_PRINT_REVIEW_REQUIRED", target, synchronized:existsSync(path.join(root,"outputs","TEST-NOTICE.json")), finalized:false}));
    process.exitCode = 3;
  } else {
    const directory = path.join(root, "outputs");
    mkdirSync(directory, {recursive:true});
    if (realpathSync(directory) !== directory) error("OUTPUT_OUTSIDE_FIXTURE");
    const output = path.join(directory, "TEST-NOTICE.json");
    if (existsSync(output) && lstatSync(output).isSymbolicLink()) error("OUTPUT_LINK_REJECTED");
    if (action === "finalize") {
      const synced = read("outputs/TEST-NOTICE.json");
      if (synced.noticeId !== source.noticeId || synced.title !== source.title || synced.window !== source.window || synced.capacity !== source.capacity) error("SYNC_REQUIRED");
    }
    writeFileSync(output, JSON.stringify({fixture:true, target, noticeId:source.noticeId, title:source.title,
      window:source.window, capacity:source.capacity, finalized:action === "finalize"},null,2)+"\n");
    console.log(JSON.stringify({state:action === "sync" ? "SYNCHRONIZED" : "FINALIZED", target,
      printReview:signoff.printReview, finalized:action === "finalize"}));
  }
} catch (caught) {
  const reasons = new Set(["INVALID_INPUT_PATH","INPUT_OUTSIDE_FIXTURE","UNAPPROVED_TARGET_OR_ACTION","MISSING_NOTICE_SOURCE_BINDING",
    "INVALID_NOTICE_SOURCE","INVALID_OPERATOR_RECORD","OUTPUT_OUTSIDE_FIXTURE","OUTPUT_LINK_REJECTED","SYNC_REQUIRED"]);
  console.error(JSON.stringify({state:"FAILED",reason:reasons.has(caught?.message) ? caught.message : "FIXTURE_IO_OR_JSON_ERROR"}));
  process.exitCode = 2;
}
